//! Port of `Components/Shared/Duck.razor (BlazorKawaii RubberDuck)` — spec 06 §7. Owner: ui-shell.
//! The SVG bodies are BlazorKawaii's output, copied verbatim from the reference renders
//! (.impeccable/mockups/inputs/kawaii/duck-*.html, colour #FCCC0A); only width / height follow `size`.

use leptos::prelude::*;

/// The kawaii rubber duck SVG (viewBox 0 0 240 240, colour #FCCC0A). Reference renders:
/// .impeccable/mockups/inputs/kawaii/duck-*.html.
#[component]
pub fn Duck(
    mood: Mood,
    #[prop(default = 48)] size: u32,
) -> impl IntoView {
    // BlazorKawaii wraps its svg in a relatively positioned div; `.duck svg{display:block}` styles the svg itself.
    view! {
        <div style="position: relative; ">
            <svg xmlns="http://www.w3.org/2000/svg" width=size height=size viewBox="0 0 240 240" fill="none"
                aria-hidden="true" inner_html=mood.svg()></svg>
        </div>
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Mood {
    Happy,
    Excited,
    Blissful,
    Sad,
    Shocked,
    Ko,
    Sleepy,
    Dizzy,
}

impl Mood {
    /// The inner SVG of this mood (body + face).
    pub fn svg(self) -> &'static str {
        match self {
            Mood::Happy => HAPPY,
            Mood::Excited => EXCITED,
            Mood::Blissful => BLISSFUL,
            Mood::Sad => SAD,
            Mood::Shocked => SHOCKED,
            Mood::Ko => KO,
            Mood::Sleepy => SLEEPY,
            Mood::Dizzy => DIZZY,
        }
    }
}

